'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {prepareInvoiceAllocation,readInvoiceAllocationReceipt,loadPendingAllocation,savePendingAllocation,clearPendingAllocation} from '@/lib/invoice-allocation';
import {readInvoicePaymentOptions} from '@/lib/invoice-payment-options';
type Props={tenant:string;property:string;invoice:string;actor:string;disabled:boolean;options:unknown};
export function InvoiceAllocationAction(props:Props){return <Action key={[props.tenant,props.property,props.invoice,props.actor].join(':')} {...props}/>;}
function Action({disabled,options,...scope}:Props){
 const [pending,setPending]=useState<ReturnType<typeof prepareInvoiceAllocation>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[consumedOptions,setConsumedOptions]=useState<unknown>(null);const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{setPending(loadPendingAllocation(sessionStorage,scope));}catch(cause){setError(cause instanceof Error?cause.message:'Cannot read pending allocation.');}return()=>{alive.current=false;};},[scope.tenant,scope.property,scope.invoice,scope.actor]);
 let payments:ReturnType<typeof readInvoicePaymentOptions>['payments']=[];try{if(options)payments=readInvoicePaymentOptions(options,scope).payments.filter(p=>p.maximum_minor!=='0');}catch{}
 function review(form:FormData){try{if(loadPendingAllocation(sessionStorage,scope))throw Error('Resolve the saved allocation first.');const request=prepareInvoiceAllocation(scope,crypto.randomUUID(),options,{entry:String(form.get('entry')),amount:String(form.get('amount')),effective_on:String(form.get('date')),reason:String(form.get('reason'))});setPending(savePendingAllocation(sessionStorage,scope,request));setConfirmed(false);setError('');setMessage('');}catch(cause){setError(cause instanceof Error?cause.message:'Review allocation details.');}}
 async function run(status:boolean,cancel=false){if(lock.current||disabled||!pending||(cancel?!cancelConfirmed:(!status&&!confirmed)))return;lock.current=true;setBusy(true);setError('');setMessage('');try{
  const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen this invoice.');if(!alive.current)return;
  const result=await hotelRpc<unknown>(cancel?'cancel_invoice_allocation_request':status?'invoice_allocation_status':'allocate_invoice_payment',cancel?{p_tenant:scope.tenant,p_property:scope.property,p_request:pending.args.p_request,p_confirmed:true}:status?{p_tenant:scope.tenant,p_property:scope.property,p_request:pending.args.p_request,p_kind:'allocation'}:pending.args);
  const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover after signing in.');if(!alive.current)return;
  if(cancel){const r=result as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.request_id!==pending.args.p_request||r.cancelled!==true||typeof r.replayed!=='boolean')throw Error('Cancellation receipt does not match this allocation.');clearPendingAllocation(sessionStorage,scope,pending.args.p_request);setPending(null);setConfirmed(false);setCancelConfirmed(false);setConsumedOptions(options);setMessage('Unrecorded allocation cancelled. Refresh payments before preparing another allocation.');return;}
  let receipt=result;if(status){const r=result as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.request_id!==pending.args.p_request||r.kind!=='allocation'||typeof r.found!=='boolean')throw Error('Allocation recovery scope changed.');if(!r.found){if(r.result!==null)throw Error('Invalid allocation recovery response.');setMessage('No allocation recorded yet. Confirm and retry the saved request.');return;}receipt=r.result;}
  readInvoiceAllocationReceipt(receipt,pending);clearPendingAllocation(sessionStorage,scope,pending.args.p_request);setPending(null);setConfirmed(false);setConsumedOptions(options);setMessage('Payment allocated. Refresh invoice balances and available payments.');
 }catch(cause){if(alive.current)setError(cause instanceof Error?cause.message:'Allocation interrupted. Check saved result.');}finally{lock.current=false;if(alive.current)setBusy(false);}}
 return <section className="pilot-settings"><h4>Apply recorded payment</h4>{!pending&&payments.length>0&&options!==consumedOptions&&<form onSubmit={e=>{e.preventDefault();review(new FormData(e.currentTarget));}}><fieldset disabled={disabled||busy}><label className="field">Payment receipt<select name="entry">{payments.map(p=><option key={p.entry_id} value={p.entry_id}>{p.reference} · maximum {usd(Number(p.maximum_minor))}</option>)}</select></label><label className="field">Allocation amount (USD)<input name="amount" inputMode="decimal" required/></label><label className="field">Allocation date<input name="date" type="date" required/></label><label className="field">Allocation reason<input name="reason" minLength={4} maxLength={500} required/></label><button>Review allocation</button></fieldset></form>}{pending&&<><p>Saved allocation: {usd(pending.args.p_amount_minor)} · {pending.args.p_effective_on}</p><p>{pending.args.p_reason}</p><label><input type="checkbox" checked={confirmed} disabled={busy||disabled} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this payment allocation</label><button disabled={busy||disabled||!confirmed} onClick={()=>void run(false)}>Apply payment / retry</button><button disabled={busy||disabled} onClick={()=>void run(true)}>Check allocation result</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy||disabled} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this request only if no allocation was recorded</label><button disabled={busy||disabled||!cancelConfirmed} onClick={()=>void run(false,true)}>Cancel unrecorded allocation</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
